<?php if(empty($openweb_guided)){http_response_code(404);exit;} ?>
<?php
/** OpenWeb PBX guided administration. Native applications retain their authorization checks. */
require_once dirname(__DIR__, 2).'/resources/require.php';
require_once PROJECT_ROOT.'/resources/check_auth.php';
$setup = new pbx_setup;
if (!$setup->canManage()) { http_response_code(403); exit('Access denied.'); }
header('Cache-Control: no-store');
header('Referrer-Policy: no-referrer');
$escape = static fn($value) => htmlspecialchars(is_scalar($value) || $value === null ? (string)$value : '', ENT_QUOTES, 'UTF-8');
$view = (string)($_GET['view'] ?? 'overview');
$error = '';
$draft = null;
$draftId = (string)($_GET['draft'] ?? '');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!(new token)->validate('/app/pbx_setup/index.php')) {
            http_response_code(403);
            throw new RuntimeException('Your form expired. Refresh the page and try again.');
        }
        switch ($_POST['action'] ?? '') {
            case 'review_setup':
                $draft = $setup->reviewSetup($_POST);
                header('Location: /app/pbx_setup/?view=review&draft='.rawurlencode($draft['draft_id'])); exit;
            case 'create_setup':
                if (empty($_POST['acknowledged'])) throw new InvalidArgumentException('Confirm the setup before creating your PBX.');
                $domain = $setup->createSetup((string)($_POST['draft_id'] ?? ''));
                $setup->switchDomain($domain);
                $_SESSION['pbx_setup_notice'] = 'Your PBX is ready. Connect your phones, then test incoming and outgoing calls.';
                header('Location: /app/pbx_setup/'); exit;
            case 'analyze_import':
                $draft = $setup->analyzeUpload($_FILES['backup'] ?? []);
                header('Location: /app/pbx_setup/?view=import_preview&draft='.rawurlencode($draft['draft_id'])); exit;
            case 'create_import':
                if (empty($_POST['acknowledge_limitations'])) throw new InvalidArgumentException('Review and acknowledge the migration report first.');
                $domain = $setup->createImport((string)($_POST['draft_id'] ?? ''), $_POST);
                $setup->switchDomain($domain);
                $_SESSION['pbx_setup_notice'] = 'The reviewed configuration was imported into a new PBX. Check the migration report and test every call flow before switching your live phones and numbers.';
                header('Location: /app/pbx_setup/'); exit;
            default: throw new InvalidArgumentException('Choose a setup action.');
        }
    } catch (PDOException $exception) {
        error_log('OpenWeb PBX guided setup failed: '.$exception->getCode());
        $error = $exception->getCode() === '23505' ? 'A PBX or user already uses these details. Choose a different service name or user number.' : 'The PBX change could not be saved. Please try again.';
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
    $view = match ($_POST['action'] ?? '') {
        'review_setup' => 'wizard', 'create_setup' => 'review', 'analyze_import' => 'import', 'create_import' => 'import_preview', default => $view
    };
    $draftId = (string)($_POST['draft_id'] ?? $draftId);
}
$views = ['overview','users','voice','handling','settings','wizard','review','import','import_preview'];
if (!in_array($view, $views, true)) $view = 'overview';
$options = $setup->options();
$overview = $setup->overview();
if (in_array($view, ['review','import_preview'], true)) {
    try { $draft = $view === 'review' ? $setup->draft($draftId) : $setup->importPreview($draftId); }
    catch (Throwable $exception) { $error = $exception->getMessage(); $view = $view === 'review' ? 'wizard' : 'import'; }
}
$counts = $overview['counts'] ?? [];
$notice = (string)($_SESSION['pbx_setup_notice'] ?? ''); unset($_SESSION['pbx_setup_notice']);
$formToken = (new token)->create('/app/pbx_setup/index.php');
$csrf = static function() use ($formToken, $escape) { echo '<input type="hidden" name="'.$escape($formToken['name']).'" value="'.$escape($formToken['hash']).'">'; };
$values = $error && ($_POST['action'] ?? '') === 'review_setup' ? $_POST : [];
$timezone = (string)($values['timezone'] ?? $options['default_timezone'] ?? 'Africa/Johannesburg');
$tenant = (string)($values['tenant_uuid'] ?? $options['current_tenant_uuid'] ?? '');
$company = (string)($values['company_name'] ?? $options['default_company_name'] ?? '');
$sourceIp = filter_var($_SERVER['SERVER_ADDR'] ?? '', FILTER_VALIDATE_IP) ?: '';
$serviceName = (string)($values['service_name'] ?? 'Main office');
$renderTenant = static function(string $selected = '') use ($options, $escape) {
    $tenants = $options['tenants'] ?? [];
    if (permission_exists('pbx_tenant_manage')) {
        echo '<label>Company workspace<select name="tenant_uuid"><option value="">My company</option>';
        foreach ($tenants as $item) echo '<option value="'.$escape($item['tenant_uuid']).'" '.($selected === $item['tenant_uuid'] ? 'selected' : '').'>'.$escape($item['tenant_name']).'</option>';
        echo '</select><small>Each company gets its own PBX settings, users, and call rules.</small></label>';
    } else echo '<input type="hidden" name="tenant_uuid" value="'.$escape($selected).'">';
};
$renderTimezone = static function(string $selected) use ($options, $escape) {
    echo '<label>Timezone<select name="timezone" required>';
    foreach ($options['timezones'] ?? DateTimeZone::listIdentifiers() as $value) echo '<option value="'.$escape($value).'" '.($selected === $value ? 'selected' : '').'>'.$escape(str_replace('_', ' ', $value)).'</option>';
    echo '</select><small>Used for office hours and voicemail timestamps.</small></label>';
};
$renderUser = static function(string|int $index, array $user = [], bool $first = false) use ($escape) {
    echo '<div class="setup-user-row" data-user-row><label>Extension<input name="users['.$escape($index).'][number]" data-user-number inputmode="numeric" pattern="[0-9]{2,9}" maxlength="9" value="'.$escape($user['number'] ?? ($first ? '100' : '')).'" '.($first ? 'required' : '').' placeholder="101"></label><label>Name<input name="users['.$escape($index).'][name]" data-user-name maxlength="80" value="'.$escape($user['name'] ?? '').'" '.($first ? 'required' : '').' placeholder="Alex Morgan"></label><label>Email <small>Optional</small><input type="email" name="users['.$escape($index).'][email]" maxlength="254" value="'.$escape($user['email'] ?? '').'" placeholder="alex@example.com"></label><button type="button" class="setup-button danger" data-remove-user aria-label="Remove this user" '.($first ? 'hidden' : '').'><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></div>';
};
$link = static function(string $permission, string $url, string $icon, string $title, string $description) use ($escape) {
    if (!permission_exists($permission)) return;
    echo '<a class="setup-link" href="'.$escape($url).'"><i class="fa-solid '.$escape($icon).'" aria-hidden="true"></i><div><strong>'.$escape($title).'</strong><span>'.$escape($description).'</span></div><i class="fa-solid fa-chevron-right" aria-hidden="true"></i></a>';
};
$document['title'] = 'Admin';
require_once PROJECT_ROOT.'/resources/header.php';
?>
