            <?php foreach (['overview'=>['fa-house','Overview'],'users'=>['fa-users','Users'],'voice'=>['fa-phone-volume','Voice & Chat'],'handling'=>['fa-diagram-project','Call handling'],'settings'=>['fa-sliders','Settings']] as $key=>$item): ?><a href="?view=<?= $key ?>" class="<?= $view === $key ? 'selected' : '' ?>" <?= $view === $key ? 'aria-current="page"' : '' ?>><i class="fa-solid <?= $item[0] ?>" aria-hidden="true"></i><?= $item[1] ?></a><?php endforeach; ?>
