                    <section data-setup-step data-title="Phone service"><h2 tabindex="-1">Connect your phone provider.</h2><p>Enter your provider's SIP trunk details. You can leave the server blank and add a provider later.</p><div class="setup-fields"><label>Provider / trunk name<input name="trunk[name]" maxlength="60" value="<?= $escape($trunk['name'] ?? 'Phone provider') ?>" placeholder="Phone provider"></label><label>SIP server<input name="trunk[host]" maxlength="253" value="<?= $escape($trunk['host'] ?? '') ?>" placeholder="sip.provider.com"><small>Use the server address supplied by your provider.</small></label><label>Port<input type="number" name="trunk[port]" min="1" max="65535" value="<?= $escape($trunk['port'] ?? '5060') ?>"></label><label>Transport<select name="trunk[transport]"><?php foreach(['udp'=>'UDP','tcp'=>'TCP','tls'=>'TLS'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($trunk['transport'] ?? 'udp') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="full">Authentication<select name="trunk[authentication]"><option value="ip" <?= $authentication === 'ip' ? 'selected' : '' ?>>IP Authentication — no username or password</option><option value="password" <?= $authentication === 'password' ? 'selected' : '' ?>>Username &amp; password</option></select></label></div><p class="setup-hint" data-ip-hint>Your provider must allow calls from this server<?= $sourceIp ? ' ('.$escape($sourceIp).')' : '' ?>. </p><div class="setup-fields" data-trunk-credentials><label>Username <small>Password authentication only</small><input name="trunk[username]" maxlength="200" value="<?= $escape($trunk['username'] ?? '') ?>" autocomplete="off"></label><label>Password <small>Password authentication only</small><input type="password" name="trunk[password]" maxlength="256" value="" autocomplete="new-password"><small>Your password is stored securely and is never shown in the review.</small></label></div></section>
